fn at(xs: List[Int], i: Int) -> Int {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return 0
        }
    }
}

pub fn rooms(meetings: List[List[Int]]) -> Int {
    var best = 0
    for m in meetings {
        let t = at(m, 0)
        var cnt = 0
        for o in meetings {
            if at(o, 0) <= t and t < at(o, 1) {
                cnt = cnt + 1
            }
        }
        if cnt > best {
            best = cnt
        }
    }
    return best
}
